prompt:
Crie um componente Direction para um projeto React + Tailwind CSS com shadcn/ui (estilo "New York", acessível via Radix UI).

Alternativa recomendada (registro oficial open source, licença MIT): instale direto com o CLI shadcn:

npx shadcn add direction

Documentação oficial: https://ui.shadcn.com/docs/components/direction

Implementação de referência (MIT — shadcn/ui):

"use client"

import * as React from "react"
import { Direction } from "radix-ui"

function DirectionProvider({
  dir,
  direction,
  children,
}: React.ComponentProps<typeof Direction.DirectionProvider> & {
  direction?: React.ComponentProps<typeof Direction.DirectionProvider>["dir"]
}) {
  return (
    <Direction.DirectionProvider dir={direction ?? dir}>
      {children}
    </Direction.DirectionProvider>
  )
}

const useDirection = Direction.useDirection

export { DirectionProvider, useDirection }
